package hn.uth.pm1ea0199.controller;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.text.*;import android.view.*;import android.widget.*;import java.io.File;import java.util.*;import hn.uth.pm1ea0199.dao.ContactoDAO;import hn.uth.pm1ea0199.model.Contacto;import hn.uth.pm1ea0199.view.Vistas;
public class ListaActivity extends Activity {
 private ContactoDAO dao;private ListView lista;private ArrayList<Contacto> contactos,visibles=new ArrayList<>();private Contacto seleccionado;private EditText buscar;private TextView vacio;
 @Override public void onCreate(Bundle s){super.onCreate(s);dao=new ContactoDAO(this);LinearLayout l=Vistas.pagina(this,"");setContentView(l);Button atras=Vistas.boton(this,l,"Atrás   ...");LinearLayout.LayoutParams al=(LinearLayout.LayoutParams)atras.getLayoutParams();al.width=Vistas.dp(this,90);atras.setLayoutParams(al);atras.setOnClickListener(v->finish());
 buscar=new EditText(this);buscar.setSingleLine(true);buscar.setTextSize(14);buscar.setHint("⌕ Buscar");buscar.setPadding(12,3,12,3);buscar.setBackground(Vistas.fondo(Color.WHITE,Color.DKGRAY,30));l.addView(buscar,new LinearLayout.LayoutParams(-1,Vistas.dp(this,40)));
 vacio=new TextView(this);vacio.setText("No hay contactos");l.addView(vacio);lista=new ListView(this);lista.setBackground(Vistas.fondo(Color.WHITE,Color.DKGRAY,0));lista.setDividerHeight(1);l.addView(lista,new LinearLayout.LayoutParams(-1,0,1));lista.setOnItemClickListener((p,v,pos,id)->{seleccionado=visibles.get(pos);lista.invalidateViews();final Contacto c=seleccionado;new AlertDialog.Builder(this).setTitle("Acción").setMessage("¿Desea llamar a "+c.nombre+"?").setNegativeButton("No",null).setPositiveButton("Sí",(d,w)->startActivity(new Intent(this,LlamarActivity.class).putExtra("id",c.id).putExtra("confirmada",true))).show();});
 LinearLayout r1=Vistas.fila(this,l);Vistas.mitad(this,r1,"Compartir Contacto").setOnClickListener(v->compartir());Vistas.mitad(this,r1,"Ver Imagen").setOnClickListener(v->verImagen());
 LinearLayout r2=Vistas.fila(this,l);Vistas.mitad(this,r2,"Eliminar Contacto").setOnClickListener(v->eliminar());Vistas.mitad(this,r2,"Actualizar Contacto").setOnClickListener(v->{if(elegido())startActivity(new Intent(this,RegistroActivity.class).putExtra("id",seleccionado.id));});
 buscar.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){filtrar();}public void afterTextChanged(Editable e){}});
 }
 private boolean elegido(){if(seleccionado!=null)return true;Vistas.alerta(this,"Selecciona un contacto de la lista. Puedes pulsar No en la confirmación para usar las otras acciones.");return false;}
 private void filtrar(){if(contactos==null)return;seleccionado=null;String q=buscar.getText().toString().trim().toLowerCase(Locale.ROOT);visibles.clear();for(Contacto c:contactos)if((c.nombre+" "+c.telefono+" "+c.pais).toLowerCase(Locale.ROOT).contains(q))visibles.add(c);vacio.setVisibility(visibles.isEmpty()?View.VISIBLE:View.GONE);vacio.setText(contactos.isEmpty()?"No hay contactos guardados":"No hay coincidencias");lista.setAdapter(new ArrayAdapter<Contacto>(this,android.R.layout.simple_list_item_1,visibles){@Override public View getView(int pos,View reutilizada,ViewGroup padre){TextView t=(TextView)super.getView(pos,reutilizada,padre);Contacto c=getItem(pos);t.setText((seleccionado!=null&&seleccionado.id==c.id?"● ":"○ ")+c.nombre+" | "+Vistas.numero(c.pais,c.telefono));t.setTextSize(13);t.setMinHeight(Vistas.dp(ListaActivity.this,40));t.setPadding(8,8,8,8);boolean azul=pos%2==1||(seleccionado!=null&&seleccionado.id==c.id);t.setBackgroundColor(azul?Color.rgb(57,139,226):Color.rgb(228,237,246));t.setTextColor(azul?Color.WHITE:Color.BLACK);return t;}});}
 private void compartir(){if(!elegido())return;Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,"Contacto: "+seleccionado.nombre);i.putExtra(Intent.EXTRA_TEXT,"Nombre: "+seleccionado.nombre+"\nPaís: "+seleccionado.pais+"\nTeléfono: "+Vistas.numero(seleccionado.pais,seleccionado.telefono)+"\nNota: "+seleccionado.nota);try{startActivity(Intent.createChooser(i,"Compartir contacto"));}catch(ActivityNotFoundException e){Vistas.alerta(this,"No hay aplicaciones para compartir.");}}
 private void verImagen(){if(!elegido())return;ImageView f=new ImageView(this);f.setAdjustViewBounds(true);f.setMaxHeight(Vistas.dp(this,380));f.setContentDescription("Fotografía de "+seleccionado.nombre);Vistas.mostrar(f,seleccionado.imagen);new AlertDialog.Builder(this).setTitle(seleccionado.nombre).setView(f).setPositiveButton("Cerrar",null).show();}
 private void eliminar(){if(!elegido())return;final Contacto c=seleccionado;new AlertDialog.Builder(this).setTitle("Eliminar contacto").setMessage("¿Eliminar a "+c.nombre+"?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{try{if(dao.eliminar(c.id)){new File(c.imagen).delete();cargar();}}catch(Exception e){Vistas.alerta(this,"No se pudo eliminar.");}}).show();}
 private void cargar(){try{contactos=dao.listar();filtrar();}catch(Exception e){Vistas.alerta(this,"No se pudieron consultar los contactos.");}}
 @Override protected void onResume(){super.onResume();cargar();}
 @Override protected void onDestroy(){dao.close();super.onDestroy();}
}
